page_header('تواصل معنا','راسل فريق ركن المعرفة لأي استفسار أو اقتراح.'); ?><section class="pageintro"><span class="eyebrow">نستمع إليك</span><h1>تواصل معنا</h1><p>أرسل اقتراحًا أو استفسارًا لفريق التحرير.</p></section><section class="panel contact-panel"><?php if($sent): ?><p class="success">وصلتنا رسالتك، شكرًا لتواصلك.</p><?php else: ?><?php if($error): ?><p class="error"><?=e($error)?></p><?php endif; ?><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>الاسم<input name="name" required maxlength="120"></label><label>البريد الإلكتروني<input type="email" name="email" required maxlength="190"></label><label>الموضوع<input name="subject" required maxlength="200"></label><label>الرسالة<textarea name="message" required rows="6"></textarea></label><button class="btn">إرسال الرسالة</button></form><?php endif; ?><p class="muted">البريد: <?=e(CONTACT_EMAIL)?></p></section><?php page_footer(); ?>
